mapper.select:
select
    c1.C_Name as roleCpyName,
     mn.*
from Sys_Role mn
left join SYS_Company c1 on c1.C_Id=mn.Role_Cpy

    
        and mn.Te_Id=#{params.teId}
    
    
        and mn.Role_Type=#{params.roleType}
    
    
        and mn.Role_Cpy=#{params.roleCpy}
    
    
        and INSTR(mn.Role_DataAuthority,#{params.roleDataauthority})
    
    
        and INSTR(mn.Role_Code,#{params.roleCode})
    
    
        and INSTR(mn.Role_Name,#{params.roleName})
    


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by mn.Role_Sort ASC
